"use client";

import { loadFont } from "@remotion/google-fonts/FunnelDisplay";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_CLOSER,
  DEFAULT_CLUES,
  type RiddleCluesElementId,
  riddleCluesTimeline,
  splitWords,
} from "./timeline";

const funnel = loadFont("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface RiddleClue {
  line: string;
  turn: string;
}

export interface RiddleCluesProps {
  clues?: RiddleClue[];
  closer?: RiddleClue;
  label?: string;
  accent?: string;
  /** Text color of the clues; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Funnel Display by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Frames between words as a line rises in. */
  stagger?: number;
  /** Size of the text block, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches single labels, words, shifts and exits, by the
   * ids in `./timeline`. Frames on the scene timeline, after `delay` and
   * `speed`.
   */
  timing?: Timing<RiddleCluesElementId>;
}

const THEMES = {
  dark: {
    bg: "#0B0B0F",
    ink: "#FFFFFF",
    dim: "rgba(255,255,255,0.42)",
    accent: "#B79CFF",
  },
  light: {
    bg: "#FAFAFA",
    ink: "#121216",
    dim: "rgba(18,18,22,0.45)",
    accent: "#6B4FD8",
  },
} as const;

const WGHT = 400;
const TRACK = -0.012;
const MEASURE_PX = 100;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_MOVE = Easing.bezier(0.65, 0, 0.25, 1);
const EASE_IN = Easing.bezier(0.55, 0, 0.8, 0.2);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

let measureCtx: CanvasRenderingContext2D | null = null;

function em(s: string, font: string) {
  if (!measureCtx) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (!measureCtx) throw new Error("riddle-clues: no 2d context");
  measureCtx.font = font;
  return (
    measureCtx.measureText(s).width / MEASURE_PX + TRACK * Array.from(s).length
  );
}

function useFontsReady(fontFamily: string, fontWeight: number) {
  const [ready, setReady] = useState(false);
  const [handle] = useState(() => delayRender("riddle-clues: fonts"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    Promise.all([
      funnel.waitUntilDone(),
      document.fonts.load(`${fontWeight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (live) setReady(true);
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [handle, fontFamily, fontWeight]);
  return ready;
}

interface Word {
  text: string;
  x: number;
}

interface Part {
  words: Word[];
  w: number;
}

interface Item {
  line: Part[];
  turn: Part[];
  inline: boolean;
}

function toPart(words: string[], font: string): Part {
  const space = em(" ", font);
  let x = 0;
  const out = words.map((text) => {
    const at = x;
    x += em(text, font) + space;
    return { text, x: at };
  });
  return { words: out, w: em(words.join(" "), font) };
}

function greedy(words: string[], maxEm: number, font: string): string[][] {
  const rows: string[][] = [];
  let cur: string[] = [];
  for (const w of words) {
    const next = [...cur, w];
    if (cur.length > 0 && em(next.join(" "), font) > maxEm) {
      rows.push(cur);
      cur = [w];
    } else {
      cur = next;
    }
  }
  if (cur.length) rows.push(cur);
  return rows;
}

function wrap(s: string, maxEm: number, font: string): Part[] {
  const words = splitWords(s);
  let rows = greedy(words, maxEm, font);
  let m = maxEm;
  for (let guard = 0; guard < 30 && rows.length > 1; guard++) {
    m *= 0.96;
    const next = greedy(words, m, font);
    if (next.length > rows.length) break;
    rows = next;
  }
  return rows.map((r) => toPart(r, font));
}

function buildLayout(items: RiddleClue[], W: number, H: number, font: string) {
  const portrait = H > W * 1.1;
  const maxW = W * (portrait ? 0.8 : 0.58);
  const F = Math.min(W, H) * (portrait ? 0.052 : 0.05);
  const gap = em(" ", font);
  const out: Item[] = items.map((it) => {
    const line = wrap(it.line, maxW / F, font);
    const turn = wrap(it.turn, maxW / F, font);
    const inline =
      line.length === 1 &&
      turn.length === 1 &&
      (line[0].w + gap + turn[0].w) * F <= maxW;
    return { line, turn, inline };
  });
  return { items: out, F, gap, portrait };
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function RiddleClues(props: RiddleCluesProps) {
  const {
    clues = DEFAULT_CLUES,
    closer = DEFAULT_CLOSER,
    label = "Clue",
    accent,
    ink,
    background,
    fontFamily = funnel.fontFamily,
    fontWeight = WGHT,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const frame = Math.max(0, useSceneFrame() - delay);
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    riddleCluesTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const hi = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const stage =
    background === "transparent" ? "transparent" : (background ?? c.bg);
  const ready = useFontsReady(fontFamily, fontWeight);
  const font = `${fontWeight} ${MEASURE_PX}px "${fontFamily}"`;

  const all = useMemo(() => [...clues, closer], [clues, closer]);
  const layout = useMemo(
    () => (ready ? buildLayout(all, W, H, font) : null),
    [ready, all, W, H, font],
  );

  if (!layout) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const { F, gap } = layout;
  const n = layout.items.length;
  const t = frame * speed;

  const rowH = F * 1.34;
  const pitch = F * 1.36;
  const cy = H / 2;
  const LF = F * 0.38;

  const nodes = layout.items.map((item, i) => {
    const isLast = i === n - 1;
    const shiftEl = tl.get(`shift:${i}`);
    const outEl = isLast ? null : tl.get(`out:${i}`);
    const firstEl = isLast
      ? (tl.elements.find((e) => e.id.startsWith(`line:${i}:`)) ?? shiftEl)
      : tl.get(`label:${i}`);
    // Before its first element and after its exit the item is out of sight.
    if (t < firstEl.start - 2) return null;
    if (outEl && t > outEl.end + 2) return null;

    const shiftAt = (l: number) =>
      interpolate(l, [shiftEl.start, shiftEl.end], [0, 1], {
        ...CLAMP,
        easing: EASE_MOVE,
      });
    const outAt = (l: number) =>
      outEl
        ? interpolate(l, [outEl.start, outEl.end], [0, 1], {
            ...CLAMP,
            easing: EASE_IN,
          })
        : 0;
    const shift = shiftAt(t);
    // A frame on either side, to tell a value still easing from one at rest.
    const dt = speed;
    const moves = (at: (l: number) => number) =>
      Math.abs(at(t + dt) - at(t)) > 1e-3 ||
      Math.abs(at(t) - at(t - dt)) > 1e-3;

    const placed: {
      part: Part;
      x: number;
      y: number;
      turn: boolean;
      first: number;
    }[] = [];
    let topY: number;
    // The block recentres as the turn arrives. Layout rounds a box and a
    // baseline to whole pixels, so the rows sit where the turn leaves them
    // and the climb there is a transform.
    let lift = (_l: number) => 0;
    if (item.inline) {
      const lineW = item.line[0].w * F;
      const turnW = item.turn[0].w * F;
      const totalW = lineW + gap * F + turnW;
      const x0 = W / 2 - lineW / 2;
      const x1 = W / 2 - totalW / 2;
      placed.push({
        part: item.line[0],
        x: x0 + (x1 - x0) * shift,
        y: cy,
        turn: false,
        first: 0,
      });
      placed.push({
        part: item.turn[0],
        x: x0 + (x1 - x0) * shift + lineW + gap * F,
        y: cy,
        turn: true,
        first: 0,
      });
      topY = cy;
    } else {
      const nl = item.line.length;
      const nt = item.turn.length;
      const lineTop0 = cy - ((nl - 1) * pitch) / 2;
      const lineTop1 = cy - ((nl + nt - 1) * pitch) / 2;
      lift = (l: number) => (lineTop0 - lineTop1) * (1 - shiftAt(l));
      let first = 0;
      item.line.forEach((part, li) => {
        placed.push({
          part,
          x: W / 2 - (part.w * F) / 2,
          y: lineTop1 + li * pitch,
          turn: false,
          first,
        });
        first += part.words.length;
      });
      first = 0;
      item.turn.forEach((part, ti) => {
        placed.push({
          part,
          x: W / 2 - (part.w * F) / 2,
          y: lineTop1 + (nl + ti) * pitch,
          turn: true,
          first,
        });
        first += part.words.length;
      });
      topY = lineTop1;
    }
    const dyLift = lift(t);
    const lifting = moves(lift);
    const liftTransform =
      Math.abs(dyLift) > 1e-3 ? `translateY(${dyLift}px)` : undefined;

    const riseAt = (l: number, id: RiddleCluesElementId) => {
      const e = tl.get(id);
      return interpolate(l, [e.start, e.end], [0, 1], {
        ...CLAMP,
        easing: EASE_OUT,
      });
    };

    const row = (
      part: Part,
      x: number,
      y: number,
      color: string,
      kind: "line" | "turn",
      first: number,
      key: string,
      climbs: boolean,
    ) => (
      <div
        key={key}
        style={{
          position: "absolute",
          left: x - F * 0.2,
          top: y - rowH / 2,
          width: part.w * F + F * 0.5,
          height: rowH,
          overflow: "hidden",
          transform: climbs ? liftTransform : undefined,
        }}
      >
        {part.words.map((w, wi) => {
          const wordAt = (l: number) =>
            (1 - riseAt(l, `${kind}:${i}:${first + wi}`)) * rowH -
            outAt(l) * rowH;
          const dy = wordAt(t);
          return (
            <div
              key={`${key}-${wi}`}
              style={{
                position: "absolute",
                left: w.x * F + F * 0.2,
                top: 0,
                height: rowH,
                fontFamily,
                fontWeight,
                fontSize: F,
                lineHeight: `${rowH}px`,
                letterSpacing: `${TRACK}em`,
                whiteSpace: "pre",
                color,
                transform: `translateY(${dy.toFixed(2)}px)${glide((climbs && lifting) || moves(wordAt))}`,
              }}
            >
              {w.text}
            </div>
          );
        })}
      </div>
    );

    const labelY = topY - rowH / 2 - LF * 1.9;
    const labelAt = (l: number) =>
      isLast
        ? 0
        : (1 - riseAt(l, `label:${i}`)) * LF * 1.6 - outAt(l) * LF * 1.6;
    const labelText = isLast ? "" : `${label} ${i + 1} of ${n - 1}`;

    return (
      <div key={`item-${i}`} style={{ position: "absolute", inset: 0 }}>
        {labelText ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              width: W,
              top: labelY,
              height: LF * 1.6,
              overflow: "hidden",
              textAlign: "center",
              transform: liftTransform,
            }}
          >
            <div
              style={{
                fontFamily,
                fontWeight,
                fontSize: LF,
                lineHeight: `${LF * 1.6}px`,
                letterSpacing: "0.14em",
                textTransform: "uppercase",
                color: c.dim,
                transform: `translateY(${labelAt(t).toFixed(2)}px)${glide(lifting || moves(labelAt))}`,
              }}
            >
              {labelText}
            </div>
          </div>
        ) : null}
        {placed.map((p, pi) =>
          row(
            p.part,
            p.x,
            p.y,
            p.turn ? hi : fg,
            p.turn ? "turn" : "line",
            p.first,
            `r-${i}-${pi}`,
            !p.turn,
          ),
        )}
      </div>
    );
  });

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>{nodes}</ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// For each clue, then the closer: its label and line rising in word by word,
// the line shifting over to make room, the turn rising in word by word, and
// (for every clue but the closer) the clue dropping out. Frames on the 30 fps
// scene timeline, after `delay` and `speed`. When the clip is too short for
// the whole motion plus a hold, the schedule is played up to 1/0.6 times
// faster (`fit`). The ids are public: a saved `timing` prop refers to them.

export type RiddleCluesElementId =
  | `label:${number}`
  | `line:${number}:${number}`
  | `shift:${number}`
  | `turn:${number}:${number}`
  | `out:${number}`;

/** A line and the turn that answers it (`RiddleClue`). */
export interface ClueLines {
  line: string;
  turn: string;
}

export interface RiddleCluesTimingProps {
  clues?: ClueLines[];
  closer?: ClueLines;
  stagger?: number;
}

export const DEFAULT_CLUES: ClueLines[] = [
  { line: "It has scenes,", turn: "but no camera." },
  { line: "It has a timeline,", turn: "but no editor." },
  { line: "It has a release date,", turn: "but no name yet." },
];

export const DEFAULT_CLOSER: ClueLines = {
  line: "Give up?",
  turn: "Answer on the 14th.",
};

export const STAGGER = 3;

const STEP = 56;
const IN_LEN = 13;
const TURN_AT = 20;
const TURN_GAP = 4;
const SHIFT_LEN = 14;
const OUT_AT = 50;
const OUT_LEN = 9;
/** Frames the closer rests at the very end, kept even on a short clip. */
const MIN_HOLD = 30;
/** The smallest `fit`: a short clip speeds the schedule up 1/0.6 at most. */
const MIN_FIT = 0.6;

export function splitWords(s: string) {
  return s.split(/\s+/).filter(Boolean);
}

// Item `i` is clue `i`; the closer is the last item. `label:<i>` raises the
// clue's label (the closer has none), `line:<i>:<j>` and `turn:<i>:<j>` are
// word `j` of its line and of its turn, each a chain. `shift:<i>` follows the
// line's first word and moves the line over as the turn arrives; the turn
// follows the shift. `out:<i>` follows the shift and drops the clue; the next
// item follows it. `length` is the clip length after `speed`: when the motion
// and the hold don't fit, every start and length shrinks by `fit`.
export const riddleCluesTimeline = defineTimeline<
  RiddleCluesElementId,
  RiddleCluesTimingProps
>(
  (
    { clues = DEFAULT_CLUES, closer = DEFAULT_CLOSER, stagger = STAGGER },
    { length },
  ) => {
    const all = [...clues, closer];
    const n = all.length;
    const lastTurnWords = splitWords(all[n - 1].turn).length;
    const motionEnd =
      (n - 1) * STEP + TURN_AT + 4 + (lastTurnWords - 1) * stagger + IN_LEN;
    const fit = Math.max(MIN_FIT, Math.min(1, (length - MIN_HOLD) / motionEnd));
    const elements: TimelineElement<RiddleCluesElementId>[] = [];
    let prevOut: RiddleCluesElementId | undefined;
    all.forEach((item, i) => {
      const s = i * STEP;
      const isLast = i === n - 1;
      const lineWords = splitWords(item.line);
      const turnWords = splitWords(item.turn);
      let lead = prevOut;
      if (!isLast) {
        elements.push({
          id: `label:${i}`,
          lane: "Labels",
          label: `clue ${i + 1}`,
          start: s * fit,
          length: IN_LEN * fit,
          follows: prevOut,
        });
        lead = `label:${i}`;
      }
      lineWords.forEach((word, j) => {
        elements.push({
          id: `line:${i}:${j}`,
          lane: "Lines",
          label: word,
          start: (s + j * stagger) * fit,
          length: IN_LEN * fit,
          follows: j > 0 ? `line:${i}:${j - 1}` : lead,
        });
      });
      elements.push({
        id: `shift:${i}`,
        lane: "Shifts",
        label: "shift",
        start: (s + TURN_AT) * fit,
        length: SHIFT_LEN * fit,
        follows: lineWords.length > 0 ? `line:${i}:0` : lead,
      });
      turnWords.forEach((word, j) => {
        elements.push({
          id: `turn:${i}:${j}`,
          lane: "Turns",
          label: word,
          start: (s + TURN_AT + TURN_GAP + j * stagger) * fit,
          length: IN_LEN * fit,
          follows: j > 0 ? `turn:${i}:${j - 1}` : `shift:${i}`,
        });
      });
      if (!isLast) {
        elements.push({
          id: `out:${i}`,
          lane: "Shifts",
          label: "out",
          start: (s + OUT_AT) * fit,
          length: OUT_LEN * fit,
          follows: `shift:${i}`,
        });
        prevOut = `out:${i}`;
      }
    });
    return elements.sort((a, b) => a.start - b.start);
  },
);
